fn parse_multiplicative(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<(f64, usize), String> {
    let (mut left, _) = parse_power(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "*" || tokens[*pos] == "/") {
        let op = tokens[*pos].clone();
        *pos += 1;

        let (right, _) = parse_power(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "*" => left * right,
            "/" => {
                if right == 0.0 {
                    return Err("Math Error: Divide by zero error!".to_string());
                }
                left / right
            }
            _ => unreachable!(),
        };
    }

    Ok((left, *pos))
