                input = Some(arg.to_string());
                break;
            }
            _ => {}
        }
        i += 1;
    }

    if let Some(input) = input {
        // Command mode
        match evaluate(&input, angle_unit) {
            Ok(result) => {
                println!("{}", format_output(result, fix, base));
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode
        repl(fix, base, angle_unit);
    }
}

fn print_help() {
    println!("Calculator REPL similar to bc(1)");
    println!();
    println!("Usage: eva [OPTIONS] [INPUT]");
    println!();
    println!("Arguments:");
    println!("  [INPUT]  Optional expression string to run eva in command mode");
    println!();
    println!("Options:");
    println!("  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]");
    println!("  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]");
    println!("  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]");
    println!("  -h, --help                     Print help");
    println!("  -V, --version                  Print version");
}

fn repl(fix: u32, base: u32, angle_unit: AngleUnit) {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut _lock = stdout.lock();
    let mut prev_answer = 0.0;
    let mut first = true;

    if first {
        eprintln!("No previous history.");
        first = false;
    }

    for line in stdin.lock().lines() {
        if let Ok(line) = line {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }

            // Replace underscore with previous answer
            let expr = line.replace("_", &prev_answer.to_string());

            match evaluate(&expr, angle_unit) {
                Ok(result) => {
                    prev_answer = result;
                    println!("{}", format_output(result, fix, base));
                }
                Err(e) => {
                    eprintln!("{}", e);
                }
            }
        }
    }
}

fn evaluate(expr: &str, angle_unit: AngleUnit) -> Result<f64, String> {
    let tokens = tokenize(expr)?;
    let tokens = balance_parentheses(tokens)?;
    let tokens = apply_implicit_multiplication(tokens);
    parse_expression(&tokens, angle_unit)
}

fn tokenize(expr: &str) -> Result<Vec<String>, String> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut in_number = false;

    for ch in expr.chars() {
        match ch {
            '0'..='9' | '.' => {
                current.push(ch);
                in_number = true;
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                if in_number {
                    if !current.is_empty() {
                        tokens.push(current.clone());
                    }
                    current.clear();
                    in_number = false;
                }
                current.push(ch);
            }
            '+' | '-' | '*' | '/' | '^' | '(' | ')' | ',' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;
                tokens.push(ch.to_string());
            }
            ' ' | '\t' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;
            }
            _ => return Err(format!("Parser Error: Unknown character '{}'", ch)),
        }
    }

    if !current.is_empty() {
        tokens.push(current);
    }

    Ok(tokens)
}

fn balance_parentheses(mut tokens: Vec<String>) -> Result<Vec<String>, String> {
    let mut open_count = 0;

    for token in &tokens {
        if token == "(" {
            open_count += 1;
        } else if token == ")" {
            open_count -= 1;
            if open_count < 0 {
                return Err("Parser Error: Unbalanced parentheses".to_string());
            }
        }
    }

    // Add closing parentheses
    while open_count > 0 {
        tokens.push(")".to_string());
        open_count -= 1;
    }

    Ok(tokens)
}

fn apply_implicit_multiplication(tokens: Vec<String>) -> Vec<String> {
    let mut result = Vec::new();

    for (i, token) in tokens.iter().enumerate() {
        result.push(token.clone());

        if i + 1 < tokens.len() {
            let next = &tokens[i + 1];

            // Check if we need implicit multiplication
            let current_is_close_or_num = token == ")" || token.chars().all(|c| c.is_numeric() || c == '.');
            let next_is_open_or_func = next == "(" || is_function(next);

            if current_is_close_or_num && next_is_open_or_func {
                result.push("*".to_string());
            }

            // Number followed by identifier (like sin)
            let current_is_num = token.chars().all(|c| c.is_numeric() || c == '.');
            let next_is_identifier = !["(", ")", "+", "-", "*", "/", "^", ","].contains(&next.as_str())
                && next.chars().all(|c| c.is_alphabetic() || c == '_');

            if current_is_num && next_is_identifier {
                result.push("*".to_string());
            }

            // Close paren followed by open paren or number
            if token == ")" && (next == "(" || next.chars().all(|c| c.is_numeric() || c == '.')) {
                result.push("*".to_string());
            }
        }
    }

    result
}

fn is_function(name: &str) -> bool {
    matches!(name,
        "sin" | "cos" | "tan" | "csc" | "sec" | "cot" |
        "sinh" | "cosh" | "tanh" |
        "asin" | "acos" | "atan" | "acsc" | "asec" | "acot" |
        "ln" | "log2" | "log10" | "log" |
        "sqrt" | "ceil" | "floor" | "abs" | "nroot"
    )
}

fn get_constants() -> HashMap<&'static str, f64> {
    let mut m = HashMap::new();
    m.insert("pi", PI);
    m.insert("e", E);
    m
}

fn parse_expression(tokens: &[String], angle_unit: AngleUnit) -> Result<f64, String> {
    let mut pos = 0;
    let result = parse_additive(tokens, &mut pos, angle_unit)?;

    if pos < tokens.len() {
        return Err("Parser Error: Too many operators, too few operands".to_string());
    }

    Ok(result)
}

fn parse_additive(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_multiplicative(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "+" || tokens[*pos] == "-") {
        let op = tokens[*pos].clone();
        *pos += 1;

        let right = parse_multiplicative(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "+" => left + right,
            "-" => left - right,
            _ => unreachable!(),
        };
    }

    Ok(left)
}

fn parse_multiplicative(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_power(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "*" || tokens[*pos] == "/") {
        let op = tokens[*pos].clone();
        *pos += 1;

        let right = parse_power(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "*" => left * right,
            "/" => {
                if right == 0.0 {
                    return Err("Math Error: Divide by zero error!".to_string());
                }
                left / right
            }
            _ => unreachable!(),
        };
    }

    Ok(left)
}

fn parse_power(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_unary(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "^" || tokens[*pos] == "**") {
        let op = tokens[*pos].clone();
        *pos += 1;

        let right = parse_unary(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "^" | "**" => left.powf(right),
            _ => unreachable!(),
        };
    }

    Ok(left)
}

fn parse_unary(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    if *pos >= tokens.len() {
        return Err("Parser Error: Unexpected end of expression".to_string());
    }

    if tokens[*pos] == "+" {
        *pos += 1;
        parse_unary(tokens, pos, angle_unit)
    } else if tokens[*pos] == "-" {
        *pos += 1;
        let val = parse_unary(tokens, pos, angle_unit)?;
        Ok(-val)
    } else {
        parse_primary(tokens, pos, angle_unit)
    }
}

fn parse_primary(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    if *pos >= tokens.len() {
        return Err("Parser Error: Unexpected end of expression".to_string());
    }

    let token = &tokens[*pos];

    // Check for function call
    if is_function(token) {
        let func_name = token.clone();
        *pos += 1;

        if *pos >= tokens.len() || tokens[*pos] != "(" {
            return Err(format!("Parser Error: Expected '(' after function '{}'", func_name));
        }
        *pos += 1;

        // Parse function arguments
        let mut args = Vec::new();
        let mut depth = 1;
        let start = *pos;

        while *pos < tokens.len() && depth > 0 {
            if tokens[*pos] == "(" {
                depth += 1;
            } else if tokens[*pos] == ")" {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            } else if tokens[*pos] == "," && depth == 1 {
                args.push(&tokens[start..*pos]);
                *pos += 1;
                let start = *pos;
                continue;
            }
            *pos += 1;
        }

        if *pos >= tokens.len() || tokens[*pos] != ")" {
            return Err("Parser Error: Mismatched parentheses".to_string());
        }

        // Last argument
        if *pos > start {
            args.push(&tokens[start..*pos]);
        }

        *pos += 1;

        // Evaluate function
        apply_function(&func_name, args, angle_unit)
    } else if token == "(" {
        *pos += 1;
        let result = parse_additive(tokens, pos, angle_unit)?;

        if *pos >= tokens.len() || tokens[*pos] != ")" {
            return Err("Parser Error: Mismatched parentheses".to_string());
        }
        *pos += 1;

        Ok(result)
    } else if let Ok(num) = token.parse::<f64>() {
        *pos += 1;
        Ok(num)
    } else {
        let constants = get_constants();
        if let Some(&val) = constants.get(token.as_str()) {
            *pos += 1;
            Ok(val)
        } else {
            Err(format!("Parser Error: Unknown token '{}'", token))
        }
    }
}

fn apply_function(func: &str, args: Vec<&[String]>, angle_unit: AngleUnit) -> Result<f64, String> {
    let arg_count = args.len();

    if arg_count == 0 {
        return Err(format!("Parser Error: Function '{}' requires arguments", func));
    }

    // Parse first argument
    let mut pos = 0;
    let arg1 = parse_additive(args[0], &mut pos, angle_unit)?;

    let result = match func {
        "sin" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            angle.sin()
        }
        "cos" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            angle.cos()
        }
        "tan" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            angle.tan()
        }
        "csc" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            let sin_val = angle.sin();
            if sin_val == 0.0 {
                return Err("Math Error: Divide by zero error!".to_string());
            }
            1.0 / sin_val
        }
        "sec" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            let cos_val = angle.cos();
            if cos_val == 0.0 {
                return Err("Math Error: Divide by zero error!".to_string());
            }
            1.0 / cos_val
        }
        "cot" => {
            let angle = convert_angle_to_radians(arg1, angle_unit);
            let tan_val = angle.tan();
            if tan_val == 0.0 {
                return Err("Math Error: Divide by zero error!".to_string());
            }
            1.0 / tan_val
        }
        "sinh" => arg1.sinh(),
        "cosh" => arg1.cosh(),
        "tanh" => arg1.tanh(),
        "asin" => {
            if arg1 < -1.0 || arg1 > 1.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            convert_angle_from_radians(arg1.asin(), angle_unit)
        }
        "acos" => {
            if arg1 < -1.0 || arg1 > 1.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            convert_angle_from_radians(arg1.acos(), angle_unit)
        }
        "atan" => convert_angle_from_radians(arg1.atan(), angle_unit),
        "acsc" => {
            if arg1 > -1.0 && arg1 < 1.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            convert_angle_from_radians((1.0 / arg1).asin(), angle_unit)
        }
        "asec" => {
            if arg1 > -1.0 && arg1 < 1.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            convert_angle_from_radians((1.0 / arg1).acos(), angle_unit)
        }
        "acot" => convert_angle_from_radians((1.0 / arg1).atan(), angle_unit),
        "ln" => {
            if arg1 <= 0.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            arg1.ln()
        }
        "log2" => {
            if arg1 <= 0.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            arg1.log2()
        }
        "log10" => {
            if arg1 <= 0.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            arg1.log10()
        }
        "log" => {
            if arg_count < 2 {
                return Err("Parser Error: log requires 2 arguments".to_string());
            }
            let mut pos2 = 0;
            let base = parse_additive(args[1], &mut pos2, angle_unit)?;
            if arg1 <= 0.0 || base <= 0.0 || base == 1.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            arg1.log(base)
        }
        "sqrt" => {
            if arg1 < 0.0 {
                return Err("Domain Error: Out of bounds!".to_string());
            }
            arg1.sqrt()
        }
        "ceil" => arg1.ceil(),
        "floor" => arg1.floor(),
        "abs" => arg1.abs(),
        "nroot" => {
            if arg_count < 2 {
                return Err("Parser Error: nroot requires 2 arguments".to_string());
            }
            let mut pos2 = 0;
            let n = parse_additive(args[1], &mut pos2, angle_unit)?;
            if n == 0.0 {
                return Err("Math Error: Divide by zero error!".to_string());
            }
            arg1.powf(1.0 / n)
        }
        _ => return Err(format!("Parser Error: Unknown function '{}'", func)),
    };

    Ok(result)
}

fn convert_angle_to_radians(angle: f64, unit: AngleUnit) -> f64 {
    match unit {
        AngleUnit::Degree => angle.to_radians(),
        AngleUnit::Radian => angle,
        AngleUnit::Gradian => angle * PI / 200.0,
    }
}

fn convert_angle_from_radians(radians: f64, unit: AngleUnit) -> f64 {
    match unit {
        AngleUnit::Degree => radians.to_degrees(),
        AngleUnit::Radian => radians,
        AngleUnit::Gradian => radians * 200.0 / PI,
    }
}

fn format_output(value: f64, fix: u32, base: u32) -> String {
    let fix = fix.max(1).min(64) as usize;

    // Format with specified decimal places
    let formatted = if base == 10 {
        // Decimal formatting with thousands separator
        format!("{:.prec$}", value, prec = fix)
    } else {
        // Base conversion formatting
        format_in_base(value, base, fix)
    };

    // Add thousands separator for decimal
    if base == 10 {
        add_thousands_separator(&formatted)
    } else {
        formatted
    }
}

fn add_thousands_separator(num_str: &str) -> String {
    let parts: Vec<&str> = num_str.split('.').collect();
    let integer_part = parts[0];
    let decimal_part = if parts.len() > 1 { parts[1] } else { "0" };

    let mut result = String::new();
    let chars: Vec<char> = integer_part.chars().collect();
    let start = if integer_part.starts_with('-') { 1 } else { 0 };

    if start == 1 {
        result.push('-');
    }

    for (i, ch) in chars[start..].iter().enumerate() {
        if i > 0 && (chars.len() - start - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*ch);
    }

    result.push('.');
    result.push_str(decimal_part);

    result
}

fn format_in_base(value: f64, base: u32, fix: usize) -> String {
    let base = base.max(1).min(36) as u32;

    let integer = value.trunc() as i64;
    let mut result = String::new();

    // Format integer part
    if integer == 0 {
        result.push('0');
    } else {
        let mut n = integer.abs();
        let mut digits = String::new();

        while n > 0 {
            let digit = (n % base as i64) as u32;
            digits.insert(0, to_digit_char(digit));
            n /= base as i64;
        }

        if integer < 0 {
            result.push('-');
        }
        result.push_str(&digits);
    }

    result.push('.');

    // Format decimal part
    let mut decimal = value.fract().abs();
    for _ in 0..fix {
        decimal *= base as f64;
        let digit = decimal.trunc() as u32;
        result.push(to_digit_char(digit));
        decimal = decimal.fract();
    }

    result
}

fn to_digit_char(digit: u32) -> char {
    match digit {
        0..=9 => (b'0' + digit as u8) as char,
        10..=35 => (b'A' + (digit - 10) as u8) as char,
        _ => '?',
    }
}
