                in_number = true;
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                if in_number {
                    if !current.is_empty() {
                        tokens.push(current.clone());
                    }
                    current.clear();
                    in_number = false;
                }
                current.push(ch);
            }
            '+' | '-' | '*' | '/' | '^' | '(' | ')' | ',' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;
                tokens.push(ch.to_string());
            }
            ' ' | '\t' => {
