                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;

                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    tokens.push("**".to_string());
                    i += 2;
                } else {
                    tokens.push("*".to_string());
                    i += 1;
                }
            }
            '+' | '-' | '/' | '^' | '(' | ')' | ',' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;
                tokens.push(ch.to_string());
                i += 1;
