fn parse_expression(tokens: &[String], angle_unit: AngleUnit) -> Result<f64, String> {
    if tokens.is_empty() {
        return Err("Parser Error: Empty expression".to_string());
    }

    let mut pos = 0;
    let result = parse_additive(tokens, &mut pos, angle_unit)?;

    if pos < tokens.len() {
        return Err("Parser Error: Too many operators, too few operands".to_string());
    }

    Ok(result)
}

fn parse_additive(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_multiplicative(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "+" || tokens[*pos] == "-") {
        let op = tokens[*pos].clone();
        *pos += 1;

        if *pos >= tokens.len() {
            return Err("Parser Error: Too many operators, too few operands".to_string());
        }

        let right = parse_multiplicative(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "+" => left + right,
            "-" => left - right,
            _ => unreachable!(),
        };
    }

    Ok(left)
}

fn parse_multiplicative(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_power(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "*" || tokens[*pos] == "/") {
        let op = tokens[*pos].clone();
        *pos += 1;

        if *pos >= tokens.len() {
            return Err("Parser Error: Too many operators, too few operands".to_string());
        }

        let right = parse_power(tokens, pos, angle_unit)?;

        left = match op.as_str() {
            "*" => left * right,
            "/" => {
                if right == 0.0 {
                    return Err("Math Error: Divide by zero error!".to_string());
                }
                left / right
            }
            _ => unreachable!(),
        };
    }

    Ok(left)
}

fn parse_power(tokens: &[String], pos: &mut usize, angle_unit: AngleUnit) -> Result<f64, String> {
    let mut left = parse_unary(tokens, pos, angle_unit)?;

    while *pos < tokens.len() && (tokens[*pos] == "^" || tokens[*pos] == "**") {
        let _op = tokens[*pos].clone();
        *pos += 1;

        if *pos >= tokens.len() {
            return Err("Parser Error: Too many operators, too few operands".to_string());
        }

        let right = parse_unary(tokens, pos, angle_unit)?;
        left = left.powf(right);
    }

    Ok(left)
