                current.push(ch);
                in_number = true;
                i += 1;
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                if in_number {
                    if !current.is_empty() {
                        tokens.push(current.clone());
                    }
                    current.clear();
                    in_number = false;
                }
                current.push(ch);
                i += 1;
            }
            '*' => {
                // Check for ** operator
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;

                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    tokens.push("**".to_string());
                    i += 2;
                } else {
                    tokens.push("*".to_string());
                    i += 1;
                }
            }
            '+' | '-' | '/' | '^' | '(' | ')' | ',' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_number = false;
                tokens.push(ch.to_string());
                i += 1;
            }
            ' ' | '\t' => {
